-- =====================================================
-- CSI Admin Portal - Database Setup
-- Run this ONCE in the Supabase SQL Editor
-- =====================================================

-- 1. Admin allowlist -----------------------------------
CREATE TABLE IF NOT EXISTS admin_users (
  email TEXT PRIMARY KEY,
  added_by TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- !!! IMPORTANT: add YOURSELF as the first admin !!!
VALUES ('studyonaffan@gmail.com', 'initial-setup')
ON CONFLICT (email) DO NOTHING;

-- 2. Magazines ------------------------------------------
CREATE TABLE IF NOT EXISTS magazines (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL,
  description TEXT,
  cover_url TEXT,
  pdf_url TEXT NOT NULL,
  pages INTEGER DEFAULT 1,
  sort_order INTEGER DEFAULT 0,
  is_active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Resources ------------------------------------------
CREATE TABLE IF NOT EXISTS resources (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL,
  description TEXT,
  image_url TEXT,
  pdf_url TEXT,
  link_url TEXT,
  sort_order INTEGER DEFAULT 0,
  is_active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Team table upgrades --------------------------------
ALTER TABLE csi_team ADD COLUMN IF NOT EXISTS portfolio TEXT;
ALTER TABLE csi_team ADD COLUMN IF NOT EXISTS gb_position TEXT;
ALTER TABLE csi_team ADD COLUMN IF NOT EXISTS team_year TEXT DEFAULT '2025-26';
CREATE INDEX IF NOT EXISTS idx_csi_team_year ON csi_team(team_year);
CREATE INDEX IF NOT EXISTS idx_csi_team_active ON csi_team(is_active);

-- 5. Storage bucket for uploads --------------------------
VALUES ('media', 'media', TRUE)
ON CONFLICT (id) DO NOTHING;

-- Public read for the media bucket
DROP POLICY IF EXISTS "media public read" ON storage.objects;
CREATE POLICY "media public read" ON storage.objects
  FOR SELECT USING (bucket_id = 'media');

-- 6. Row Level Security ----------------------------------
ALTER TABLE admin_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE magazines ENABLE ROW LEVEL SECURITY;
ALTER TABLE resources ENABLE ROW LEVEL SECURITY;

-- Public read for site content (writes go through service role, which bypasses RLS)
DROP POLICY IF EXISTS "magazines public read" ON magazines;
CREATE POLICY "magazines public read" ON magazines FOR SELECT USING (TRUE);
DROP POLICY IF EXISTS "resources public read" ON resources;
CREATE POLICY "resources public read" ON resources FOR SELECT USING (TRUE);

-- =====================================================
-- 7. SEED DATA (run once; skip this section if re-running)
-- =====================================================

-- Clear existing team rows to avoid duplicates when seeding
-- (comment out the next line if you already have team data you want to keep)
DELETE FROM csi_team;



-- =====================================================
-- 8. EVENT SEEDS (from the old JSON files)
-- =====================================================
ALTER TABLE events ADD COLUMN IF NOT EXISTS subtitle TEXT;
ALTER TABLE events ADD COLUMN IF NOT EXISTS organizers TEXT[];
ALTER TABLE events ADD COLUMN IF NOT EXISTS highlights TEXT[];
ALTER TABLE events ADD COLUMN IF NOT EXISTS contacts JSONB;
ALTER TABLE events ADD COLUMN IF NOT EXISTS time_range TEXT;


