INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('Volunteer Appreciation Ceremony','Celebrating Our Heroes','As you all know, CSI and E-Cell successfully organized a Hack Revolution 2025 this November, and it wouldn''t have been possible without the incredible effort and dedication from our volunteers! Join us for a short and sweet ceremony filled with appreciation, gratitude, and of course, good vibes!','/events/past/hackrev.jpg','completed','2025-12-12T14:30:00.000Z',NULL,'Seminar Hall','Ceremony',ARRAY['Team CSI']::TEXT[],ARRAY['Appreciation & Gratitude','Good Vibes','Celebration of contribution']::TEXT[],'[{"name": "Team CSI", "phone": "csi@mjcollege.ac.in"}]'::jsonb,'Afternoon',ARRAY['Volunteer','Appreciation','CSI']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('Dev Showdown','Execom Project Showcase','You are invited to ''Dev Showdown'', a project showcase by our very own Execom members! Come and watch the teams present the exciting projects they have been working on. Discover creative and practical tech solutions, get inspiration for your future projects, and connect with the CSI technical community.','/events/past/devshowdown.jpg','completed','2025-12-06T13:45:00.000Z',NULL,'Lab 4','Showcase',ARRAY['CSI MJCET']::TEXT[],ARRAY['Discover creative and practical tech solutions','Get inspiration for your future projects','Learn new ideas, workflows, and approaches','Connect with the CSI technical community']::TEXT[],NULL,'1:45 PM – 4:00 PM',ARRAY['Project Showcase','Innovation','Tech']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('Antigravity Unlocked','Powered by Gemini','Antigravity is trending. AI is evolving. But only a few actually understand what’s coming next. Are you ready to be one of them? Join us for “Antigravity Unlocked Powered by Gemini”, a hands-on journey into the world of Agentic AI and Google’s revolutionary Antigravity framework.','/events/past/antigravity.jpg','completed','2025-12-05T13:45:00.000Z',NULL,'Student Activity Centre','Workshop',ARRAY['Computer Science and Engineering Department','CSI MJCET']::TEXT[],ARRAY['Discover what Agentic AI truly means','Deep dive into Google Antigravity','Hands-on Mini Challenge','Exciting Google swags & exclusive giveaways for winners!']::TEXT[],'[{"name": "Abdullah", "phone": "77802 27803"}, {"name": "Touseef", "phone": "99895 98636"}]'::jsonb,'1:45 PM – 4:00 PM',ARRAY['AI','Google','Agentic AI','Workshop']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('CSI Community Connect','The Ultimate CSI Community Meetup','Brace yourselves because we’re bringing the ultimate CSI COMMUNITY CONNECT! Insanely fun activities, team bonding like never before, high-energy group challenges, and pure chaos + laughter. Meet the entire CSI fam and start the year with a bang!','/events/past/community.jpg','completed','2025-11-28T13:45:00.000Z',NULL,'Student Activity Center, Block 1','Community',ARRAY['CSI MJCET']::TEXT[],ARRAY['Insanely fun activities','Team bonding like never before','High-energy group challenges','Meet the entire CSI fam']::TEXT[],NULL,'1:45 PM – Onwards',ARRAY['Community','Fun','Networking']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('Prompt Arena','Outsmart. Outcreate. Outprompt.','Think you can outsmart AI? Think you can craft prompts that stand out? This is your chance to prove it in a high-energy competition where creativity meets logic and technology! Gear up for 3 electrifying rounds, from a mind-bending Quiz to an intense Prompt Battle and a thrilling Mystery Round!','/events/past/promptarena.jpg','completed','2025-11-21T13:45:00.000Z',NULL,'Seminar Hall, Block 4','Competition',ARRAY['Computer Science and Engineering Department','CSI MJCET']::TEXT[],ARRAY['3 Electrifying Rounds: Quiz, Prompt Battle, Mystery Round','Team Size: 2–3 members','Registration Fee: Absolutely FREE','Exciting prizes to be won']::TEXT[],'[{"name": "Touseef", "phone": "99895 98636"}, {"name": "Affan", "phone": "91217 95950"}]'::jsonb,'1:45 PM – 4:00 PM',ARRAY['AI','Prompt Engineering','Competition','Creativity']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('Hack Revolution 2025','Biggest Flagship Event | Powered by Aces','Get ready to witness the ultimate tech face-off where innovation meets impact. Brought to you by the ultimate duo CSI x E-Cell MJCET a 15-hour coding marathon designed to challenge your creativity, logic, and problem-solving like never before. Win incredible cash prizes from a massive pool of ₹3,00,000! Winners get direct entry to Smart India Hackathon 2026.','/events/past/hackrev.jpg','completed','2025-11-08T09:00:00.000Z',NULL,'Ghulam Ahmed Hall MJCET','Hackathon',ARRAY['CSI MJCET','E-Cell MJCET','ACES']::TEXT[],ARRAY['4 Competitive Tracks: Smart Ed, Urban Tech, Agri & Open Hardware','₹3,00,000 Cash Prize Pool','Direct entry to SIH 2026 for winners','15-hour coding marathon']::TEXT[],'[{"name": "Abdullah", "phone": "77802 27803"}, {"name": "Rayyan", "phone": "99087 84538"}]'::jsonb,'9:00 AM – Onwards',ARRAY['Hackathon','Innovation','Coding','Smart India Hackathon']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('Terraview 2025: Turning Data into Stories','The Ultimate First Year Showdown | Powered by ACES','Exclusively for First-Years! Step into the world of data visualization and show your mettle! This isn’t just any competition, it’s your chance to turn raw data into jaw-dropping insights. Compete for a ₹30,000 cash prize pool! This is a SOLO event - it’s just you, your data, and your vision.','/events/past/teraview2.jpg','completed','2025-11-08T10:00:00.000Z',NULL,'Seminar Hall, Block 4','Competition',ARRAY['ACES','CSI MJCET','E-Cell MJCET']::TEXT[],ARRAY['Exclusively for First-Years','₹30,000 Cash Prize Pool','SOLO Event','Live Presentation Finals']::TEXT[],'[{"name": "Abdullah Shareef", "phone": "77802 27803"}, {"name": "Rayyan", "phone": "99087 84538"}]'::jsonb,'10:00 AM – 1:00 PM',ARRAY['Data Visualization','Competition','Terraview','First Years']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('Data Analytics using Terraview','Turning Data into Stories','First Years Exclusive! Get ready to explore the world of data with Terraview, the platform that transforms raw numbers into impactful insights. Whether you’re a beginner or a curious innovator, this hands-on session will help you craft dashboards that impress and prepare for Terraview 2025 with a ₹30,000 cash prize pool!','/events/past/terraview.jpg','completed','2025-10-29T13:30:00.000Z',NULL,'CIC Lab Block 2','Workshop',ARRAY['ACES','CSI MJCET','E-Cell MJCET']::TEXT[],ARRAY['Fundamentals of data visualization & analytics','Hands on experience with Terraview','Skills to create impactful data stories','Expert tips to shine in Terraview 2025','Certificate of participation']::TEXT[],'[{"name": "Abdullah Shareef", "phone": "77802 27803"}, {"name": "Rayyan", "phone": "99087 84538"}]'::jsonb,'1:30 PM – 4:00 PM',ARRAY['Data Analytics','Terraview','Visualization']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('VisionVerse','The Official Pre-Hackathon Workshop Series of Hack Revolution','Join us for VisionVerse an immersive workshop introducing you to Computer Vision, where machines learn to see and understand the world like humans. In the age of AI, Computer Vision is everywhere! From robotics to smart apps. Learn the skills that help machines see, think, and act. Fee: ₹50/- (Free for CSI & E-Cell Members!)','/events/past/visionverse.jpg','completed','2025-10-25T09:30:00.000Z',NULL,'CIC Lab, Block 2','Workshop',ARRAY['CSI MJCET','E-Cell MJCET']::TEXT[],ARRAY['Fundamentals of Computer Vision & AI','Image processing and object detection','Build hands-on projects with OpenCV / Python','Important Modules of Mediapipe','Real-world applications and workflows']::TEXT[],'[{"name": "Abdullah", "phone": "77802 27803"}, {"name": "Rayyan", "phone": "99087 84538"}]'::jsonb,'9:30 AM – 4:00 PM',ARRAY['Computer Vision','AI','OpenCV','Python']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('WEBVERSE','The Official Pre-Hackathon Workshop Series Of Hackrevolution','CSI and E-Cell MJCET proudly bring you WEBVERSE 🌐– The Web Development Workshop, the first pre-hackathon session of Hack Revolution. Before the hackathon begins, step into the world of web technologies and learn how to turn your ideas into dynamic, creative, and functional web solutions.','/events/past/webverse.jpg','completed','2024-11-16T10:00:00.000Z','2024-11-16T14:00:00.000Z','Lab 301, MJCET','Workshop',ARRAY['CSI MJCET','E-Cell MJCET']::TEXT[],ARRAY['Get Ready to Build the Web of Tomorrow!','Learn React, Next.js, and TypeScript','Turn ideas into dynamic web solutions']::TEXT[],NULL,NULL,ARRAY['Web Development','React','Workshop']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('SIH Decoded – Hear it from the Winners!','Guidance for Smart India Hackathon','Want to Participate in SIH but need guidance? Hear it from the Winners! In 2024, Two CSI teams from MJCET Won SIH. Now, they’re here to share how they did it. Whether you’re curious about hackathons, planning to participate in SIH, or just want to learn from the winners, this session is for you! Fee: ₹50 (Free for CSI Members).','/events/past/sihdecoded.jpg','completed','2025-09-19T10:30:00.000Z',NULL,'CIC Lab, Block 2','Seminar',ARRAY['CSI MJCET']::TEXT[],ARRAY['Live Interaction with SIH 2024 winners','PS Selection Tips – how to choose the right problem statement','Guide to making a Winning PPT','Journey from PS selection to the finale']::TEXT[],'[{"name": "Touseef Banu", "phone": "99895 98636"}, {"name": "Affan Asif", "phone": "91217 95950"}]'::jsonb,'10:30 AM – 1:00 PM',ARRAY['SIH','Hackathon','Guidance','Success Story']::TEXT[],TRUE);
INSERT INTO events (title,subtitle,description,poster_url,status,event_date,event_end_date,venue,category,organizers,highlights,contacts,time_range,tags,is_active) VALUES ('ADSOPHOS 2026','Unleash the Future','ADSOPHOS 2026 is a vibrant two-day fest where fun, creativity, and culinary delights come together. It''s a space to explore, compete, and enjoy a variety of exciting activities with your friends.
